const filas = $input.all().map(i => i.json);
const grupos = {};
for (const f of filas) {
  if (!grupos[f.proveedor]) grupos[f.proveedor] = [];
  grupos[f.proveedor].push(f);
}
let texto = 'LISTA DE COMPRAS SUGERIDA - La Cantina del Cafe\n';
for (const [prov, items] of Object.entries(grupos)) {
  texto += `\n${prov}:\n`;
  for (const it of items) {
    texto += `- ${it.articulo}: stock ${Number(it.stock_actual)} / minimo ${Number(it.stock_minimo)} ${it.unidad} -> pedir aprox. ${Number(it.cantidad_sugerida)} ${it.unidad}\n`;
  }
}
return [{ json: { mensaje: texto, total: filas.length } }];
